from scipy import stats
import matplotlib.pyplot as plt
def task_func(data_dict, data_keys):
    if data_dict is None:
        raise ValueError("data_dict must not be None.")
    if data_keys is None or len(data_keys) != 2:
        raise ValueError("data_keys must contain exactly two keys.")

    x_key, y_key = data_keys
    if x_key not in data_dict or y_key not in data_dict:
        raise KeyError("Both data_keys must exist in data_dict.")

    try:
        x_raw = list(data_dict[x_key])
        y_raw = list(data_dict[y_key])
    except TypeError as exc:
        raise TypeError("Both data series must be iterable.") from exc

    if len(x_raw) != len(y_raw):
        raise ValueError("The two data series must have the same length.")

    x_vals, y_vals = [], []
    for x, y in zip(x_raw, y_raw):
        try:
            x_float = float(x)
            y_float = float(y)
        except (TypeError, ValueError) as exc:
            raise ValueError("All data values must be numeric.") from exc

        if x_float == x_float and y_float == y_float and abs(x_float) != float("inf") and abs(y_float) != float("inf"):
            x_vals.append(x_float)
            y_vals.append(y_float)

    fig, ax = plt.subplots()
    ax.scatter(x_vals, y_vals)
    ax.set_xlabel(str(x_key))
    ax.set_ylabel(str(y_key))

    if len(x_vals) < 2:
        corr_coef = float("nan")
    elif len(set(x_vals)) < 2 or len(set(y_vals)) < 2:
        corr_coef = float("nan")
    else:
        corr_coef = float(stats.pearsonr(x_vals, y_vals).statistic)

    return corr_coef, ax
